out = Path(sys.argv[1])
only = set(sys.argv[2:])
for name, (refs, body) in PANELS.items():
    if only and name not in only:
        continue
    (out / f'{name}.txt').write_text(HEAD + '\n' + refs + '\n\n' + body + '\n' + TAIL + '\n', encoding='utf-8')
    print(name)
